import { useEffect, useMemo, useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import axios from 'axios'
import { Controller, useForm } from 'react-hook-form'
import {
  Alert, Avatar, Box, Button, Card, Chip, CircularProgress, Dialog, DialogActions, DialogContent,
  DialogTitle, Divider, Drawer, FormControl, FormHelperText, IconButton, InputAdornment,
  InputLabel, MenuItem, Select, Snackbar, Stack, Switch, Table, TableBody, TableCell, TableHead, TableRow,
  TextField, Tooltip, Typography,
} from '@mui/material'
import DashboardRoundedIcon from '@mui/icons-material/DashboardRounded'
import SmartToyRoundedIcon from '@mui/icons-material/SmartToyRounded'
import CallRoundedIcon from '@mui/icons-material/CallRounded'
import MenuRoundedIcon from '@mui/icons-material/MenuRounded'
import NotificationsNoneRoundedIcon from '@mui/icons-material/NotificationsNoneRounded'
import AddRoundedIcon from '@mui/icons-material/AddRounded'
import ArrowOutwardRoundedIcon from '@mui/icons-material/ArrowOutwardRounded'
import ArrowForwardRoundedIcon from '@mui/icons-material/ArrowForwardRounded'
import CheckCircleRoundedIcon from '@mui/icons-material/CheckCircleRounded'
import ErrorOutlineRoundedIcon from '@mui/icons-material/ErrorOutlineRounded'
import PhoneInTalkRoundedIcon from '@mui/icons-material/PhoneInTalkRounded'
import QueryStatsRoundedIcon from '@mui/icons-material/QueryStatsRounded'
import AccountBalanceWalletRoundedIcon from '@mui/icons-material/AccountBalanceWalletRounded'
import HeadsetMicRoundedIcon from '@mui/icons-material/HeadsetMicRounded'
import HubRoundedIcon from '@mui/icons-material/HubRounded'
import AccessTimeRoundedIcon from '@mui/icons-material/AccessTimeRounded'
import SearchRoundedIcon from '@mui/icons-material/SearchRounded'
import KeyRoundedIcon from '@mui/icons-material/KeyRounded'
import ContentCopyRoundedIcon from '@mui/icons-material/ContentCopyRounded'
import DarkModeRoundedIcon from '@mui/icons-material/DarkModeRounded'
import LightModeRoundedIcon from '@mui/icons-material/LightModeRounded'

type Page = 'Customers' | 'Agents' | 'Numbers' | 'Overview' | 'API' | 'Call Logs' | 'Workspace'
type Account = { tenant_id: string; display_name: string; billing_mode: 'prepaid' | 'postpaid'; created_at: string; vertex_project?: { status: string } }
type Agent = { id: string; name: string; language: string; voice: string; speaking_style: string; instructions: string; enabled: boolean; created_at: string }
type Plan = { voice_enabled: boolean; currency: string; rate_per_minute_minor: number; max_call_seconds: number; allowed_channels: string[]; max_concurrent_sessions: number; recording_allowed: boolean; prepaid_balance_minor: number; postpaid_credit_limit_minor: number }
type Integration = { provider: string; credentials_configured: string[]; settings: Record<string, unknown>; phone_numbers: { number: string; inbound_enabled: boolean; outbound_enabled: boolean }[] }
type RecentCall = { session_id: string; provider: string; channel: string; status: string; destination: string; created_at: string }
type ApiKey = { id: string; name: string; key_prefix: string; scopes: string[]; created_by: string; created_at: string; expires_at: string | null; last_used_at: string | null; revoked_at: string | null }
type CreatedApiKey = { id: string; name: string; key: string; key_prefix: string; scopes: string[]; created_at: string; expires_at: string | null; message: string }
type Customer = { customer_id: string; display_name: string; billing_mode: 'prepaid' | 'postpaid'; created_at: string }
type CustomerApiKey = { id: string; name: string; key_prefix: string; scopes: string[]; created_by: string; created_at: string; expires_at: string | null; last_used_at: string | null; revoked_at: string | null }
type ProvisionedCustomer = Customer & { api_key: string; api_key_record: CustomerApiKey; message: string; vertex_project?: { status: string } }

const agentLanguages = [
  { tag: 'en-US', label: 'English (US)' },
  { tag: 'ta-IN', label: 'Tamil · தமிழ் (India)' },
  { tag: 'ml-IN', label: 'Malayalam · മലയാളം (India)' },
  { tag: 'te-IN', label: 'Telugu · తెలుగు (India)' },
]
const geminiVoices = [
  ['Zephyr', 'Bright'], ['Kore', 'Firm'], ['Orus', 'Firm'], ['Autonoe', 'Bright'],
  ['Umbriel', 'Easy-going'], ['Erinome', 'Clear'], ['Laomedeia', 'Upbeat'], ['Schedar', 'Even'],
  ['Achird', 'Friendly'], ['Sadachbia', 'Lively'], ['Puck', 'Upbeat'], ['Fenrir', 'Excitable'],
  ['Aoede', 'Breezy'], ['Enceladus', 'Breathy'], ['Algieba', 'Smooth'], ['Algenib', 'Gravelly'],
  ['Achernar', 'Soft'], ['Gacrux', 'Mature'], ['Zubenelgenubi', 'Casual'], ['Sadaltager', 'Knowledgeable'],
  ['Charon', 'Informative'], ['Leda', 'Youthful'], ['Callirrhoe', 'Easy-going'], ['Iapetus', 'Clear'],
  ['Despina', 'Smooth'], ['Rasalgethi', 'Informative'], ['Alnilam', 'Firm'], ['Pulcherrima', 'Forward'],
  ['Vindemiatrix', 'Gentle'], ['Sulafat', 'Warm'],
]

const API_BASE = (import.meta.env.VITE_API_URL || '').replace(/\/$/, '')
const API_KEY_SCOPES = ['calls:read', 'calls:write', 'agents:read', 'agents:write', 'integrations:read', 'integrations:write', 'billing:read', 'webhooks:read', 'webhooks:write']
const CUSTOMER_API_KEY_SCOPES = [...API_KEY_SCOPES, 'accounts:read']
const http = axios.create({ baseURL: API_BASE, timeout: 30000 })
http.interceptors.request.use((config) => {
  const token = localStorage.getItem('chiefvoice.token')
  if (token) config.headers.Authorization = `Bearer ${token}`
  return config
})
const api = {
  account: () => http.get<Account>('/v1/accounts/current').then(r => r.data),
  createAccount: (body: { display_name: string; billing_mode: string }) => http.post<Account>('/v1/accounts', body).then(r => r.data),
  agents: () => http.get<{ items: Agent[] }>('/v1/agents').then(r => r.data.items),
  saveAgent: (body: AgentForm) => http.post<Agent>('/v1/agents', body).then(r => r.data),
  plan: () => http.get<Plan>('/v1/billing/current').then(r => r.data),
  savePlan: (body: Record<string, unknown>) => http.put<Plan>('/v1/billing/current', body).then(r => r.data),
  integration: () => http.get<Integration>('/v1/integrations/vobiz').then(r => r.data),
  saveIntegration: (body: Record<string, unknown>) => http.put('/v1/integrations/vobiz', body).then(r => r.data),
  call: (body: Record<string, unknown>) => http.post('/v1/calls/outbound', body, { headers: { 'Idempotency-Key': `web-${crypto.randomUUID()}` } }).then(r => r.data),
  callStatus: (id: string) => http.get(`/v1/calls/${id}`).then(r => r.data),
  postCall: (id: string) => http.get(`/v1/calls/${id}/post-call`).then(r => r.data),
  health: () => http.get('/readyz').then(r => r.data),
  apiKeys: () => http.get<{ items: ApiKey[] }>('/v1/api-keys').then(r => r.data.items),
  createApiKey: (body: { name: string; scopes: string[]; expires_at?: string }) => http.post<CreatedApiKey>('/v1/api-keys', body).then(r => r.data),
  revokeApiKey: (id: string) => http.delete(`/v1/api-keys/${id}`),
  customers: () => http.get<{ items: Customer[] }>('/v1/admin/customers').then(r => r.data.items),
  createCustomer: (body: { display_name: string; billing_mode: 'prepaid' | 'postpaid'; api_key_name: string; api_key_scopes: string[] }) => http.post<ProvisionedCustomer>('/v1/admin/customers', body).then(r => r.data),
  customerKeys: (id: string) => http.get<{ items: CustomerApiKey[] }>(`/v1/admin/customers/${id}/api-keys`).then(r => r.data.items),
  issueCustomerKey: (id: string, body: { name: string; scopes: string[] }) => http.post<{ key: string; api_key_record: CustomerApiKey }>(`/v1/admin/customers/${id}/api-keys`, body).then(r => r.data),
  revokeCustomerKey: (customerId: string, keyId: string) => http.delete(`/v1/admin/customers/${customerId}/api-keys/${keyId}`),
}
const errorMessage = (error: unknown) => axios.isAxiosError(error) ? (error.response?.data?.detail || error.message) : 'Something went wrong. Please try again.'
const recentKey = 'chiefvoice.recentCalls'
const getRecent = (): RecentCall[] => { try { return JSON.parse(localStorage.getItem(recentKey) || '[]') as RecentCall[] } catch { return [] } }
const saveRecent = (call: RecentCall) => localStorage.setItem(recentKey, JSON.stringify([call, ...getRecent().filter(x => x.session_id !== call.session_id)].slice(0, 12)))
const money = (minor?: number, currency = 'USD') => new Intl.NumberFormat(undefined, { style: 'currency', currency, maximumFractionDigits: 2 }).format((minor || 0) / 100)

type AgentForm = { name: string; language: string; voice: string; speaking_style: string; instructions: string }
type CallForm = { destination: string; caller_id: string; agent_id: string; context: string }
type AccountForm = { display_name: string; billing_mode: 'prepaid' | 'postpaid' }
type PlanForm = { currency: string; rate_per_minute_minor: number; max_call_seconds: number; max_concurrent_sessions: number; prepaid_balance_minor: number; postpaid_credit_limit_minor: number; voice_enabled: boolean; recording_allowed: boolean }
type IntegrationForm = { auth_id: string; auth_token: string; default_caller_id: string; number: string }
type ApiKeyForm = { name: string; scopes: string[]; expires_days: string }
type CustomerForm = { display_name: string; billing_mode: 'prepaid' | 'postpaid'; api_key_name: string; api_key_scopes: string[] }

function App({ mode, onToggleTheme }: { mode: 'light' | 'dark'; onToggleTheme: () => void }) {
  const qc = useQueryClient()
  const [page, setPage] = useState<Page>('Customers')
  const [drawer, setDrawer] = useState(false)
  const [tokenOpen, setTokenOpen] = useState(false)
  const [token, setToken] = useState(localStorage.getItem('chiefvoice.token') || '')
  const [toast, setToast] = useState('')
  const [agentOpen, setAgentOpen] = useState(false)
  const [editingAgent, setEditingAgent] = useState<Agent | null>(null)
  const [callOpen, setCallOpen] = useState(false)
  const [apiKeyOpen, setApiKeyOpen] = useState(false)
  const [createdApiKey, setCreatedApiKey] = useState<CreatedApiKey | null>(null)
  const [createdCustomerKey, setCreatedCustomerKey] = useState<{ customerName: string; key: string; scopes: string[] } | null>(null)
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null)
  const [customerOpen, setCustomerOpen] = useState(false)
  const [customerKeyOpen, setCustomerKeyOpen] = useState(false)
  const [statusId, setStatusId] = useState('')
  const [statusLookup, setStatusLookup] = useState('')
  const tokenReady = Boolean(localStorage.getItem('chiefvoice.token'))
  const accountQ = useQuery({ queryKey: ['account'], queryFn: api.account, enabled: tokenReady })
  const agentsQ = useQuery({ queryKey: ['agents'], queryFn: api.agents, enabled: tokenReady })
  const planQ = useQuery({ queryKey: ['plan'], queryFn: api.plan, enabled: tokenReady })
  const integrationQ = useQuery({ queryKey: ['integration'], queryFn: api.integration, enabled: tokenReady })
  const apiKeysQ = useQuery({ queryKey: ['api-keys'], queryFn: api.apiKeys, enabled: tokenReady && page === 'API' })
  const customersQ = useQuery({ queryKey: ['customers'], queryFn: api.customers, enabled: tokenReady && page === 'Customers', retry: false })
  const customerKeysQ = useQuery({ queryKey: ['customer-keys', selectedCustomer?.customer_id], queryFn: () => api.customerKeys(selectedCustomer!.customer_id), enabled: tokenReady && page === 'Customers' && Boolean(selectedCustomer) })
  const healthQ = useQuery({ queryKey: ['health'], queryFn: api.health, enabled: tokenReady, refetchInterval: 60000 })
  const recent = useMemo(getRecent, [toast])
  const activeAgents = agentsQ.data?.filter(a => a.enabled) || []
  const nav: { label: Page; icon: JSX.Element }[] = [
    { label: 'Customers', icon: <HubRoundedIcon /> },
    { label: 'Agents', icon: <SmartToyRoundedIcon /> }, { label: 'Numbers', icon: <HubRoundedIcon /> },
    { label: 'Overview', icon: <DashboardRoundedIcon /> }, { label: 'API', icon: <KeyRoundedIcon /> }, { label: 'Call Logs', icon: <CallRoundedIcon /> },
  ]
  const onPage = (next: Page) => { setPage(next); setDrawer(false) }
  const notifyError = (error: unknown) => setToast(errorMessage(error))
  const accountMutation = useMutation({ mutationFn: api.createAccount, onSuccess: data => { qc.setQueryData(['account'], data); setToast('Workspace created') }, onError: notifyError })
  const agentMutation = useMutation({ mutationFn: api.saveAgent, onSuccess: () => { qc.invalidateQueries({ queryKey: ['agents'] }); setAgentOpen(false); setToast('Voice agent created') }, onError: notifyError })
  const updateAgentMutation = useMutation({ mutationFn: ({ id, body }: { id: string; body: AgentForm }) => http.put(`/v1/agents/${id}`, body), onSuccess: () => { qc.invalidateQueries({ queryKey: ['agents'] }); setAgentOpen(false); setEditingAgent(null); setToast('Voice agent updated') }, onError: notifyError })
  const archiveAgentMutation = useMutation({ mutationFn: (id: string) => http.delete(`/v1/agents/${id}`), onSuccess: () => { qc.invalidateQueries({ queryKey: ['agents'] }); setToast('Voice agent archived') }, onError: notifyError })
  const callMutation = useMutation({ mutationFn: api.call, onSuccess: data => { saveRecent({ session_id: data.session_id, provider: data.provider, channel: data.channel, status: data.status, destination: callForm.getValues('destination'), created_at: new Date().toISOString() }); setCallOpen(false); setPage('Call Logs'); setToast(`Call request accepted · ${data.session_id.slice(0, 8)}`); qc.invalidateQueries({ queryKey: ['call-status'] }) }, onError: notifyError })
  const planMutation = useMutation({ mutationFn: api.savePlan, onSuccess: () => { qc.invalidateQueries({ queryKey: ['plan'] }); setToast('Voice plan saved') }, onError: notifyError })
  const integrationMutation = useMutation({ mutationFn: api.saveIntegration, onSuccess: () => { qc.invalidateQueries({ queryKey: ['integration'] }); setToast('Vobiz integration saved') }, onError: notifyError })
  const apiKeyMutation = useMutation({ mutationFn: api.createApiKey, onSuccess: key => { qc.invalidateQueries({ queryKey: ['api-keys'] }); setCreatedApiKey(key); setApiKeyOpen(false); setToast('API key created. Copy it now; it will only be shown once.') }, onError: notifyError })
  const revokeApiKeyMutation = useMutation({ mutationFn: api.revokeApiKey, onSuccess: () => { qc.invalidateQueries({ queryKey: ['api-keys'] }); setToast('API key revoked') }, onError: notifyError })
  const customerMutation = useMutation({ mutationFn: api.createCustomer, onSuccess: result => { qc.invalidateQueries({ queryKey: ['customers'] }); setSelectedCustomer(result); setCustomerOpen(false); setCreatedCustomerKey({ customerName: result.display_name, key: result.api_key, scopes: result.api_key_record.scopes }); setToast('Customer provisioned. Copy the API key now; it is shown only once.') }, onError: notifyError })
  const customerKeyMutation = useMutation({ mutationFn: ({ id, body }: { id: string; body: { name: string; scopes: string[] } }) => api.issueCustomerKey(id, body), onSuccess: result => { if (selectedCustomer) qc.invalidateQueries({ queryKey: ['customer-keys', selectedCustomer.customer_id] }); setCustomerKeyOpen(false); setCreatedCustomerKey({ customerName: selectedCustomer?.display_name || 'Customer', key: result.key, scopes: result.api_key_record.scopes }); setToast('Customer API key issued. Copy it now; it is shown only once.') }, onError: notifyError })
  const revokeCustomerKeyMutation = useMutation({ mutationFn: ({ customerId, keyId }: { customerId: string; keyId: string }) => api.revokeCustomerKey(customerId, keyId), onSuccess: () => { if (selectedCustomer) qc.invalidateQueries({ queryKey: ['customer-keys', selectedCustomer.customer_id] }); setToast('Customer API key revoked') }, onError: notifyError })
  const callStatusQ = useQuery({ queryKey: ['call-status', statusLookup], queryFn: () => api.callStatus(statusLookup), enabled: Boolean(statusLookup), refetchInterval: query => ['starting', 'initiated', 'answered'].includes(query.state.data?.status) ? 5000 : false })
  const postCallQ = useQuery({ queryKey: ['post-call', statusLookup], queryFn: () => api.postCall(statusLookup), enabled: Boolean(statusLookup && callStatusQ.data?.status === 'completed') })
  const agentForm = useForm<AgentForm>({ defaultValues: { name: '', language: 'en-US', voice: 'Charon', speaking_style: 'friendly', instructions: '' } })
  const callForm = useForm<CallForm>({ defaultValues: { destination: '', caller_id: '', agent_id: '', context: '' } })
  const accountForm = useForm<AccountForm>({ defaultValues: { display_name: '', billing_mode: 'prepaid' } })
  const planForm = useForm<PlanForm>({ defaultValues: { currency: planQ.data?.currency || 'USD', rate_per_minute_minor: planQ.data?.rate_per_minute_minor ?? 25, max_call_seconds: planQ.data?.max_call_seconds ?? 300, max_concurrent_sessions: planQ.data?.max_concurrent_sessions ?? 2, prepaid_balance_minor: planQ.data?.prepaid_balance_minor ?? 5000, postpaid_credit_limit_minor: planQ.data?.postpaid_credit_limit_minor ?? 5000, voice_enabled: planQ.data?.voice_enabled ?? false, recording_allowed: planQ.data?.recording_allowed ?? false } })
  const integrationForm = useForm<IntegrationForm>({ defaultValues: { auth_id: '', auth_token: '', default_caller_id: '', number: integrationQ.data?.phone_numbers?.[0]?.number || '' } })
  const apiKeyForm = useForm<ApiKeyForm>({ defaultValues: { name: '', scopes: ['calls:read'], expires_days: '90' } })
  const customerForm = useForm<CustomerForm>({ defaultValues: { display_name: '', billing_mode: 'prepaid', api_key_name: 'Primary API key', api_key_scopes: ['calls:read', 'calls:write'] } })
  useEffect(() => {
    if (planQ.data) planForm.reset({ currency: planQ.data.currency, rate_per_minute_minor: planQ.data.rate_per_minute_minor, max_call_seconds: planQ.data.max_call_seconds, max_concurrent_sessions: planQ.data.max_concurrent_sessions, prepaid_balance_minor: planQ.data.prepaid_balance_minor, postpaid_credit_limit_minor: planQ.data.postpaid_credit_limit_minor, voice_enabled: planQ.data.voice_enabled, recording_allowed: planQ.data.recording_allowed })
  }, [planQ.data, planForm.reset])
  useEffect(() => {
    if (integrationQ.data) integrationForm.reset({ auth_id: '', auth_token: '', default_caller_id: String(integrationQ.data.settings.default_caller_id || ''), number: integrationQ.data.phone_numbers[0]?.number || '' })
  }, [integrationQ.data, integrationForm.reset])
  const login = () => { if (!token.trim()) return; localStorage.setItem('chiefvoice.token', token.trim()); setTokenOpen(false); qc.clear(); setToast('Connected to Chiefvoice API') }
  const logout = () => { localStorage.removeItem('chiefvoice.token'); setToken(''); qc.clear(); setToast('Disconnected') }
  const startCall = callForm.handleSubmit(values => callMutation.mutate({ provider: 'vobiz', channel: 'phone', destination: values.destination, caller_id: values.caller_id || undefined, live_agent: values.agent_id ? { agent_id: values.agent_id, context: values.context ? { caller_context: values.context } : {} } : undefined }))

  const sidebar = <>
    <div className="brand"><div className="brand-mark"><HeadsetMicRoundedIcon fontSize="small" /></div><div className="brand-word">chief<span>voice</span></div></div>
    <div className="nav-caption">Menu</div>
    <div className="nav-list">{nav.map(item => <Button key={item.label} className={`nav-item ${page === item.label ? 'active' : ''}`} onClick={() => onPage(item.label)} startIcon={item.icon}>{item.label}</Button>)}</div>
  </>

  return <div className={`app-shell ${mode === 'dark' ? 'theme-dark' : ''}`}>
    <aside className="sidebar">{sidebar}</aside>
    <Drawer open={drawer} onClose={() => setDrawer(false)} PaperProps={{ sx: { width: 248, bgcolor: '#101b2d', color: 'white', p: 2 } }}><div className="sidebar open" style={{ position: 'static', width: 'auto', minHeight: '100%', padding: 0 }}>{sidebar}</div></Drawer>
    <main className="main-area">
      <header className="topbar">
        <Stack direction="row" alignItems="center" gap={1}><IconButton className="mobile-menu" onClick={() => setDrawer(true)}><MenuRoundedIcon /></IconButton><div><div className="eyebrow">{page === 'Customers' ? 'Platform console' : accountQ.data?.display_name || 'Workspace console'}</div></div></Stack>
        <div className="auth-bar">
          <Chip size="small" icon={tokenReady ? <CheckCircleRoundedIcon /> : <ErrorOutlineRoundedIcon />} label={tokenReady ? 'API connected' : 'Not connected'} color={tokenReady ? 'success' : 'default'} variant="outlined" sx={{ fontSize: 11, height: 27 }} />
          <Tooltip title={`Switch to ${mode === 'light' ? 'dark' : 'light'} theme`}><IconButton size="small" onClick={onToggleTheme} aria-label="Toggle color theme">{mode === 'light' ? <DarkModeRoundedIcon fontSize="small" /> : <LightModeRoundedIcon fontSize="small" />}</IconButton></Tooltip>
          <Tooltip title="Notifications"><IconButton size="small"><NotificationsNoneRoundedIcon fontSize="small" /></IconButton></Tooltip>
          {tokenReady ? <Button size="small" onClick={logout} color="inherit">Disconnect</Button> : <Button size="small" variant="contained" onClick={() => setTokenOpen(true)}>Connect API</Button>}
          <Avatar sx={{ width: 31, height: 31, bgcolor: '#e7eaff', color: '#465bd2', fontSize: 12, fontWeight: 800 }}>{(accountQ.data?.display_name || 'CV').slice(0, 2).toUpperCase()}</Avatar>
        </div>
      </header>
      <div className="content">
        {page === 'Customers' && <CustomersPage connected={tokenReady} onConnect={() => setTokenOpen(true)} customers={customersQ.data || []} loading={customersQ.isLoading} error={customersQ.error} selected={selectedCustomer} onSelect={setSelectedCustomer} keys={customerKeysQ.data || []} keysLoading={customerKeysQ.isLoading} keysError={customerKeysQ.error} onCreate={() => { customerForm.reset({ display_name: '', billing_mode: 'prepaid', api_key_name: 'Primary API key', api_key_scopes: ['calls:read', 'calls:write'] }); setCustomerOpen(true) }} onIssueKey={() => { customerForm.reset({ display_name: '', billing_mode: 'prepaid', api_key_name: 'Replacement API key', api_key_scopes: ['calls:read', 'calls:write'] }); setCustomerKeyOpen(true) }} onRevokeKey={keyId => { if (selectedCustomer && window.confirm('Revoke this customer key? Requests using it will fail immediately.')) revokeCustomerKeyMutation.mutate({ customerId: selectedCustomer.customer_id, keyId }) }} />}
        {page === 'Overview' && <Overview account={accountQ.data} agents={activeAgents} plan={planQ.data} integration={integrationQ.data} recent={recent} health={healthQ.data} onCreateCall={() => { callForm.reset(); setCallOpen(true) }} onCreateAgent={() => { setEditingAgent(null); agentForm.reset(); setAgentOpen(true) }} onNavigate={onPage} error={tokenReady ? (accountQ.isError && !axios.isAxiosError(accountQ.error) ? errorMessage(accountQ.error) : '') : ''} />}
        {page === 'Agents' && <AgentsPage agents={agentsQ.data || []} loading={agentsQ.isLoading} onCreate={() => { setEditingAgent(null); agentForm.reset(); setAgentOpen(true) }} onEdit={agent => { setEditingAgent(agent); agentForm.reset({ name: agent.name, language: agent.language, voice: agent.voice, speaking_style: agent.speaking_style, instructions: agent.instructions }); setAgentOpen(true) }} onArchive={agent => { if (window.confirm(`Archive “${agent.name}”?`)) archiveAgentMutation.mutate(agent.id) }} />}
        {page === 'Call Logs' && <CallsPage recent={recent} statusId={statusId} setStatusId={setStatusId} statusLookup={statusLookup} setStatusLookup={setStatusLookup} statusQuery={callStatusQ} postCallQuery={postCallQ} onCreate={() => { callForm.reset(); setCallOpen(true) }} />}
        {page === 'Numbers' && <IntegrationsPage data={integrationQ.data} loading={integrationQ.isLoading} form={integrationForm} onSave={integrationForm.handleSubmit(v => integrationMutation.mutate({ credentials: { auth_id: v.auth_id, auth_token: v.auth_token }, settings: { default_caller_id: v.default_caller_id }, phone_numbers: [{ number: v.number, inbound_enabled: true, outbound_enabled: true }] }))} busy={integrationMutation.isPending} />}
        {page === 'API' && <ApiKeysPage keys={apiKeysQ.data || []} loading={apiKeysQ.isLoading} error={apiKeysQ.error} onCreate={() => { apiKeyForm.reset({ name: '', scopes: ['calls:read'], expires_days: '90' }); setApiKeyOpen(true) }} onRevoke={id => { if (window.confirm('Revoke this API key? Applications using it will lose access immediately.')) revokeApiKeyMutation.mutate(id) }} />}
        {page === 'Workspace' && <WorkspacePage account={accountQ.data} accountError={accountQ.error} accountForm={accountForm} onCreateAccount={accountForm.handleSubmit(v => accountMutation.mutate(v))} plan={planQ.data} planForm={planForm} onSavePlan={planForm.handleSubmit(v => planMutation.mutate({ ...v, allowed_channels: ['phone'], ...(accountQ.data?.billing_mode === 'prepaid' ? { postpaid_credit_limit_minor: null } : { prepaid_balance_minor: null }) }))} busy={accountMutation.isPending || planMutation.isPending} />}
      </div>
    </main>

    <Dialog open={tokenOpen} onClose={() => setTokenOpen(false)} maxWidth="sm" fullWidth><DialogTitle sx={{ fontFamily: 'Manrope', fontWeight: 800 }}>Connect to your API</DialogTitle><DialogContent><Stack gap={2} sx={{ mt: 1 }}><TextField label="Bearer token" value={token} onChange={e => setToken(e.target.value)} placeholder="OIDC access token or cv_live_…" fullWidth autoFocus /><div className="token-dialog-note">Your token is stored in this browser only and sent to the API as a Bearer token. Customer management needs an allowlisted OIDC identity with platform:customers:read and platform:customers:write. Tenant API keys can access only their customer’s data.</div><TextField label="API base URL" value={API_BASE || 'Same origin (Vite proxies to localhost:8000)'} disabled fullWidth size="small" /></Stack></DialogContent><DialogActions sx={{ p: 2.5 }}><Button onClick={() => setTokenOpen(false)}>Cancel</Button><Button variant="contained" onClick={login} disabled={!token.trim()}>Connect</Button></DialogActions></Dialog>
    <Dialog open={agentOpen} onClose={() => setAgentOpen(false)} maxWidth="sm" fullWidth><DialogTitle sx={{ fontFamily: 'Manrope', fontWeight: 800 }}>{editingAgent ? 'Edit voice agent' : 'Create voice agent'}</DialogTitle><DialogContent><Stack component="form" id="agent-form" gap={2} sx={{ mt: 1 }} onSubmit={agentForm.handleSubmit(v => editingAgent ? updateAgentMutation.mutate({ id: editingAgent.id, body: v }) : agentMutation.mutate(v))}>
      <TextField label="Agent name" placeholder="Appointment assistant" {...agentForm.register('name', { required: 'Give your agent a name', maxLength: 100 })} error={!!agentForm.formState.errors.name} helperText={agentForm.formState.errors.name?.message} />
      <Stack direction={{ xs: 'column', sm: 'row' }} gap={2}>
        <Controller name="language" control={agentForm.control} render={({ field }) => <FormControl fullWidth><InputLabel>Language</InputLabel><Select {...field} label="Language">{agentLanguages.map(language => <MenuItem key={language.tag} value={language.tag}>{language.label}</MenuItem>)}</Select></FormControl>} />
        <Controller name="voice" control={agentForm.control} render={({ field }) => <FormControl fullWidth><InputLabel>Voice</InputLabel><Select {...field} label="Voice">{geminiVoices.map(([name, quality]) => <MenuItem key={name} value={name}>{name} · {quality}</MenuItem>)}</Select></FormControl>} />
      </Stack>
      <Controller name="speaking_style" control={agentForm.control} render={({ field }) => <FormControl fullWidth><InputLabel>Speaking style</InputLabel><Select {...field} label="Speaking style">{['professional', 'friendly', 'casual', 'slang'].map(x => <MenuItem value={x} key={x}>{x === 'slang' ? 'Regional slang (mild)' : x[0].toUpperCase() + x.slice(1)}</MenuItem>)}</Select><FormHelperText>Slang adapts to Tamil, Malayalam, or Telugu; it stays mild and avoids stereotyped dialects.</FormHelperText></FormControl>} />
      <TextField label="Instructions" multiline minRows={4} placeholder="How should this agent speak and help callers?" {...agentForm.register('instructions', { maxLength: 6000 })} helperText="Keep instructions clear, concise, and focused on the caller’s task." />
    </Stack></DialogContent><DialogActions sx={{ p: 2.5 }}><Button onClick={() => setAgentOpen(false)}>Cancel</Button><Button form="agent-form" type="submit" variant="contained" disabled={agentMutation.isPending || updateAgentMutation.isPending}>{agentMutation.isPending || updateAgentMutation.isPending ? 'Saving…' : editingAgent ? 'Save changes' : 'Create agent'}</Button></DialogActions></Dialog>
    <Dialog open={callOpen} onClose={() => setCallOpen(false)} maxWidth="sm" fullWidth><DialogTitle sx={{ fontFamily: 'Manrope', fontWeight: 800 }}>Start an outbound call</DialogTitle><DialogContent><Stack component="form" id="call-form" gap={2} sx={{ mt: 1 }} onSubmit={startCall}>
      <Alert severity="info" sx={{ fontSize: 12 }}>Calls use the Vobiz phone channel and your active workspace billing plan.</Alert>
      <TextField label="Destination phone" placeholder="+1 555 123 4567" {...callForm.register('destination', { required: 'Enter a destination', minLength: 3 })} error={!!callForm.formState.errors.destination} helperText={callForm.formState.errors.destination?.message || 'Use international E.164 format when possible.'} />
      <TextField label="Caller ID (optional)" placeholder="Use your Vobiz default caller ID" {...callForm.register('caller_id')} />
      <Controller name="agent_id" control={callForm.control} render={({ field }) => <FormControl fullWidth><InputLabel>Voice agent</InputLabel><Select {...field} label="Voice agent"><MenuItem value="">Default agent</MenuItem>{activeAgents.map(a => <MenuItem key={a.id} value={a.id}>{a.name} · {a.language}</MenuItem>)}</Select><FormHelperText>Choose the voice and instructions for this call.</FormHelperText></FormControl>} />
      <TextField label="Caller context (optional)" multiline minRows={3} placeholder="Relevant details the agent should know…" {...callForm.register('context')} />
    </Stack></DialogContent><DialogActions sx={{ p: 2.5 }}><Button onClick={() => setCallOpen(false)}>Cancel</Button><Button form="call-form" type="submit" variant="contained" startIcon={<CallRoundedIcon />} disabled={callMutation.isPending}>{callMutation.isPending ? 'Starting…' : 'Start call'}</Button></DialogActions></Dialog>
    <Dialog open={apiKeyOpen} onClose={() => setApiKeyOpen(false)} maxWidth="sm" fullWidth><DialogTitle sx={{ fontFamily: 'Manrope', fontWeight: 800 }}>Create API key</DialogTitle><DialogContent><Stack component="form" id="api-key-form" gap={2} sx={{ mt: 1 }} onSubmit={apiKeyForm.handleSubmit(v => apiKeyMutation.mutate({ name: v.name, scopes: v.scopes, ...(v.expires_days === 'never' ? {} : { expires_at: new Date(Date.now() + Number(v.expires_days) * 86400000).toISOString() }) }))}>
      <Alert severity="info" sx={{ fontSize: 12 }}>API keys are created by your OIDC account and shown only once. Choose the minimum access this key needs.</Alert>
      <TextField label="Key name" placeholder="Production call service" {...apiKeyForm.register('name', { required: 'Enter a name for this key', maxLength: 100 })} error={!!apiKeyForm.formState.errors.name} helperText={apiKeyForm.formState.errors.name?.message} />
      <Controller name="scopes" control={apiKeyForm.control} rules={{ validate: values => values.length > 0 || 'Select at least one scope' }} render={({ field, fieldState }) => <FormControl fullWidth error={!!fieldState.error}><InputLabel>Permissions</InputLabel><Select {...field} multiple label="Permissions" renderValue={selected => (selected as string[]).join(', ')}>{API_KEY_SCOPES.map(scope => <MenuItem key={scope} value={scope}><span style={{ flex: 1 }}>{scope}</span>{field.value.includes(scope) && <CheckCircleRoundedIcon color="primary" fontSize="small" />}</MenuItem>)}</Select><FormHelperText>{fieldState.error?.message || 'Only scopes granted to your current OIDC token can be selected.'}</FormHelperText></FormControl>} />
      <Controller name="expires_days" control={apiKeyForm.control} render={({ field }) => <FormControl fullWidth><InputLabel>Expiration</InputLabel><Select {...field} label="Expiration"><MenuItem value="30">30 days</MenuItem><MenuItem value="90">90 days</MenuItem><MenuItem value="365">1 year</MenuItem><MenuItem value="never">Never</MenuItem></Select></FormControl>} />
      <Alert severity="warning" sx={{ fontSize: 11 }}>This form intentionally excludes billing administration and API-key management permissions.</Alert>
    </Stack></DialogContent><DialogActions sx={{ p: 2.5 }}><Button onClick={() => setApiKeyOpen(false)}>Cancel</Button><Button form="api-key-form" type="submit" variant="contained" disabled={apiKeyMutation.isPending}>{apiKeyMutation.isPending ? 'Creating…' : 'Create key'}</Button></DialogActions></Dialog>
    <Dialog open={!!createdApiKey} onClose={() => setCreatedApiKey(null)} maxWidth="sm" fullWidth><DialogTitle sx={{ fontFamily: 'Manrope', fontWeight: 800 }}>Copy your new API key</DialogTitle><DialogContent><Stack gap={2} sx={{ mt: 1 }}><Alert severity="warning">This is the only time the full key will be shown. Store it somewhere secure before closing.</Alert><TextField label="API key" value={createdApiKey?.key || ''} fullWidth multiline minRows={2} InputProps={{ readOnly: true, endAdornment: <InputAdornment position="end"><Tooltip title="Copy key"><IconButton onClick={() => { if (createdApiKey) { void navigator.clipboard.writeText(createdApiKey.key); setToast('API key copied') } }}><ContentCopyRoundedIcon /></IconButton></Tooltip></InputAdornment> }} /><Typography sx={{ fontSize: 12, color: 'text.secondary' }}>Permissions: {createdApiKey?.scopes.join(', ')}</Typography></Stack></DialogContent><DialogActions sx={{ p: 2.5 }}><Button variant="contained" onClick={() => setCreatedApiKey(null)}>I’ve saved it</Button></DialogActions></Dialog>
    <Dialog open={customerOpen} onClose={() => setCustomerOpen(false)} maxWidth="sm" fullWidth>
      <DialogTitle sx={{ fontFamily: 'Manrope', fontWeight: 800 }}>Provision a customer</DialogTitle><DialogContent>
        <Stack component="form" id="customer-form" gap={2} sx={{ mt: 1 }} onSubmit={customerForm.handleSubmit(v => customerMutation.mutate(v))}>
          <Alert severity="info" sx={{ fontSize: 12 }}>The account and first customer-bound API key are created together. This customer can later create multiple agents and phone numbers under this account.</Alert>
          <TextField label="Customer / company name" placeholder="Acme Health" {...customerForm.register('display_name', { required: 'Enter a customer name', maxLength: 200 })} error={!!customerForm.formState.errors.display_name} helperText={customerForm.formState.errors.display_name?.message} />
          <Controller name="billing_mode" control={customerForm.control} render={({ field }) => <FormControl fullWidth><InputLabel>Billing type</InputLabel><Select {...field} label="Billing type"><MenuItem value="prepaid">Prepaid</MenuItem><MenuItem value="postpaid">Postpaid</MenuItem></Select><FormHelperText>Billing type is selected for this customer account.</FormHelperText></FormControl>} />
          <TextField label="Initial API key name" {...customerForm.register('api_key_name', { required: true, maxLength: 100 })} />
          <Controller name="api_key_scopes" control={customerForm.control} rules={{ validate: values => values.length > 0 || 'Select at least one permission' }} render={({ field, fieldState }) => <FormControl fullWidth error={!!fieldState.error}><InputLabel>Initial key permissions</InputLabel><Select {...field} multiple label="Initial key permissions" renderValue={selected => (selected as string[]).join(', ')}>{CUSTOMER_API_KEY_SCOPES.map(scope => <MenuItem key={scope} value={scope}><span style={{ flex: 1 }}>{scope}</span>{field.value.includes(scope) && <CheckCircleRoundedIcon color="primary" fontSize="small" />}</MenuItem>)}</Select><FormHelperText>{fieldState.error?.message || 'Grant only the scopes this customer’s integration needs.'}</FormHelperText></FormControl>} />
        </Stack>
      </DialogContent><DialogActions sx={{ p: 2.5 }}><Button onClick={() => setCustomerOpen(false)}>Cancel</Button><Button form="customer-form" type="submit" variant="contained" disabled={customerMutation.isPending}>{customerMutation.isPending ? 'Provisioning…' : 'Create customer'}</Button></DialogActions>
    </Dialog>
    <Dialog open={customerKeyOpen} onClose={() => setCustomerKeyOpen(false)} maxWidth="sm" fullWidth>
      <DialogTitle sx={{ fontFamily: 'Manrope', fontWeight: 800 }}>Issue another customer key</DialogTitle><DialogContent>
        <Stack component="form" id="customer-key-form" gap={2} sx={{ mt: 1 }} onSubmit={customerForm.handleSubmit(v => selectedCustomer && customerKeyMutation.mutate({ id: selectedCustomer.customer_id, body: { name: v.api_key_name, scopes: v.api_key_scopes } }))}>
          <Alert severity="info" sx={{ fontSize: 12 }}>Issue and install a replacement key first, then revoke the old key to rotate credentials without downtime.</Alert>
          <TextField label="Key name" {...customerForm.register('api_key_name', { required: true, maxLength: 100 })} />
          <Controller name="api_key_scopes" control={customerForm.control} render={({ field }) => <FormControl fullWidth><InputLabel>Permissions</InputLabel><Select {...field} multiple label="Permissions" renderValue={selected => (selected as string[]).join(', ')}>{CUSTOMER_API_KEY_SCOPES.map(scope => <MenuItem key={scope} value={scope}>{scope}</MenuItem>)}</Select></FormControl>} />
        </Stack>
      </DialogContent><DialogActions sx={{ p: 2.5 }}><Button onClick={() => setCustomerKeyOpen(false)}>Cancel</Button><Button form="customer-key-form" type="submit" variant="contained" disabled={customerKeyMutation.isPending}>{customerKeyMutation.isPending ? 'Issuing…' : 'Issue key'}</Button></DialogActions>
    </Dialog>
    <Dialog open={!!createdCustomerKey} onClose={() => setCreatedCustomerKey(null)} maxWidth="sm" fullWidth>
      <DialogTitle sx={{ fontFamily: 'Manrope', fontWeight: 800 }}>Save customer API key</DialogTitle><DialogContent><Stack gap={2} sx={{ mt: 1 }}>
        <Alert severity="warning">The full key is shown once. Copy it into the customer’s secret manager before closing.</Alert><Typography sx={{ fontSize: 12 }}>Customer: <b>{createdCustomerKey?.customerName}</b></Typography>
        <TextField label="API key" value={createdCustomerKey?.key || ''} fullWidth multiline minRows={2} InputProps={{ readOnly: true, endAdornment: <InputAdornment position="end"><Tooltip title="Copy key"><IconButton onClick={() => { if (createdCustomerKey) { void navigator.clipboard.writeText(createdCustomerKey.key); setToast('API key copied') } }}><ContentCopyRoundedIcon /></IconButton></Tooltip></InputAdornment> }} />
        <Typography sx={{ fontSize: 12, color: 'text.secondary' }}>Permissions: {createdCustomerKey?.scopes.join(', ')}</Typography>
      </Stack></DialogContent><DialogActions sx={{ p: 2.5 }}><Button variant="contained" onClick={() => setCreatedCustomerKey(null)}>I’ve saved it</Button></DialogActions>
    </Dialog>
    <Snackbar open={!!toast} autoHideDuration={5000} onClose={() => setToast('')} anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}><Alert onClose={() => setToast('')} severity={toast.toLowerCase().includes('·') || toast.includes('created') || toast.includes('saved') || toast.includes('Connected') || toast.includes('revoked') || toast.includes('copied') ? 'success' : 'error'} variant="filled">{toast}</Alert></Snackbar>
  </div>
}

function PageIntro({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle: string; action?: React.ReactNode }) { return <div style={{ display: 'flex', alignItems: 'end', justifyContent: 'space-between', gap: 18, flexWrap: 'wrap' }}><div><div className="eyebrow">{eyebrow}</div><Typography className="page-title" variant="h4">{title}</Typography><div className="page-subtitle">{subtitle}</div></div>{action}</div> }
function StatCard({ label, value, helper, icon, tone = '#eef0ff', color = '#4b60d8' }: { label: string; value: string; helper: string; icon: React.ReactNode; tone?: string; color?: string }) { return <Card className="stat-card"><div className="stat-label">{label}</div><div className="stat-number">{value}</div><div className="stat-helper">{helper}</div><div className="stat-icon" style={{ background: tone, color }}>{icon}</div></Card> }
function StatusChip({ status }: { status?: string }) { const s = (status || 'unknown').toLowerCase(); const color = ['completed', 'ready', 'initiated', 'configured', 'answered'].includes(s) ? 'success' : ['failed', 'not_ready', 'rejected'].includes(s) ? 'error' : ['starting', 'pending', 'provisioning', 'queued', 'processing'].includes(s) ? 'warning' : 'default'; return <Chip size="small" label={s.replaceAll('_', ' ')} color={color} variant={color === 'default' ? 'outlined' : 'filled'} sx={{ textTransform: 'capitalize', fontWeight: 700, fontSize: 10, height: 23 }} /> }

function Overview({ account, agents, plan, integration, recent, health, onCreateCall, onCreateAgent, onNavigate, error }: { account?: Account; agents: Agent[]; plan?: Plan; integration?: Integration; recent: RecentCall[]; health: any; onCreateCall: () => void; onCreateAgent: () => void; onNavigate: (page: Page) => void; error: string }) {
  const readyCount = health?.checks ? Object.values(health.checks).filter(Boolean).length : 0
  return <>
    <PageIntro eyebrow={new Intl.DateTimeFormat(undefined, { weekday: 'long', month: 'long', day: 'numeric' }).format(new Date()).toUpperCase()} title={`Good to see you${account?.display_name ? `, ${account.display_name}` : ''}`} subtitle="Here’s what’s happening across your voice workspace." action={<Button variant="contained" startIcon={<AddRoundedIcon />} onClick={onCreateCall}>New call</Button>} />
    {!account && <Alert severity="info" sx={{ mt: 3 }}>Your workspace is not set up yet. Contact your administrator to enable calling.</Alert>}
    {error && <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert>}
    <Box className="page-grid" sx={{ mt: 3 }}>
      <div className="span-3"><StatCard label="VOICE AGENTS" value={String(agents.length).padStart(2, '0')} helper="Ready to take a call" icon={<SmartToyRoundedIcon />} /></div>
      <div className="span-3"><StatCard label="ACTIVE CALLS" value="—" helper="Call history is kept in this browser" icon={<PhoneInTalkRoundedIcon />} tone="#e4f7f1" color="#10a783" /></div>
      <div className="span-3"><StatCard label="VOICE BALANCE" value={account?.billing_mode === 'prepaid' && plan ? money(plan.prepaid_balance_minor, plan.currency) : account?.billing_mode === 'postpaid' && plan ? money(plan.postpaid_credit_limit_minor, plan.currency) : '—'} helper={plan ? `${money(plan.rate_per_minute_minor, plan.currency)} / minute` : 'Billing plan not configured'} icon={<AccountBalanceWalletRoundedIcon />} tone="#fff3e5" color="#d68c28" /></div>
      <div className="span-3"><StatCard label="API READINESS" value={health?.status === 'ready' ? 'Ready' : health ? `${readyCount} / ${Object.keys(health.checks || {}).length}` : '—'} helper={health?.status === 'ready' ? 'Services are reporting ready' : 'Check workspace setup'} icon={<QueryStatsRoundedIcon />} tone="#e9f1ff" color="#4b80c9" /></div>
      <div className="span-8"><Card className="surface-card" sx={{ height: '100%' }}><div className="section-heading" style={{ margin: '0 0 4px' }}><h2>Call activity</h2><Button size="small" endIcon={<ArrowForwardRoundedIcon />} onClick={() => onNavigate('Call Logs')}>View calls</Button></div><div className="page-subtitle">Recent outbound activity</div>{recent.length ? <Table size="small" sx={{ mt: 2 }}><TableHead><TableRow><TableCell className="table-head">Destination</TableCell><TableCell className="table-head">Provider</TableCell><TableCell className="table-head">Started</TableCell><TableCell className="table-head">Status</TableCell></TableRow></TableHead><TableBody>{recent.slice(0, 4).map(c => <TableRow key={c.session_id}><TableCell className="table-cell" sx={{ fontWeight: 700 }}>{c.destination || 'Outbound call'}</TableCell><TableCell className="table-cell">{c.provider}</TableCell><TableCell className="table-cell">{new Date(c.created_at).toLocaleString()}</TableCell><TableCell className="table-cell"><StatusChip status={c.status} /></TableCell></TableRow>)}</TableBody></Table> : <div className="empty-state"><div style={{ width: 48, height: 48, borderRadius: 15, background: '#f1f3fa', display: 'grid', placeItems: 'center', margin: '0 auto 12px', color: '#73809a' }}><AccessTimeRoundedIcon /></div><b style={{ color: '#36425a', fontSize: 13 }}>Your call activity will show up here</b><div style={{ fontSize: 12, marginTop: 6 }}>Start a call to see call status and activity.</div><Button sx={{ mt: 1.5 }} size="small" onClick={onCreateCall}>Start your first call</Button></div>}</Card></div>
      <div className="span-4"><Card className="surface-card" sx={{ height: '100%' }}><h2 style={{ font: '700 16px Manrope', margin: '0 0 15px' }}>Quick actions</h2><Stack gap={1}><Button className="quick-action" onClick={onCreateAgent}><div className="quick-icon"><SmartToyRoundedIcon fontSize="small" /></div><span style={{ flex: 1, textAlign: 'left' }}>Create a voice agent</span><ArrowForwardRoundedIcon sx={{ fontSize: 16, color: '#98a1b2' }} /></Button><Button className="quick-action" onClick={() => onNavigate('Numbers')}><div className="quick-icon" style={{ background: '#e6f7f2', color: '#13a582' }}><HubRoundedIcon fontSize="small" /></div><span style={{ flex: 1, textAlign: 'left' }}>Connect Vobiz number</span><ArrowForwardRoundedIcon sx={{ fontSize: 16, color: '#98a1b2' }} /></Button><Button className="quick-action" onClick={() => onNavigate('Call Logs')}><div className="quick-icon" style={{ background: '#fff4e6', color: '#c7832c' }}><CallRoundedIcon fontSize="small" /></div><span style={{ flex: 1, textAlign: 'left' }}>View call logs</span><ArrowForwardRoundedIcon sx={{ fontSize: 16, color: '#98a1b2' }} /></Button></Stack></Card></div>
      <div className="span-12"><div className="call-banner" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 20 }}><div><h2>Your voice team is ready when you are.</h2><p>{integration ? 'Vobiz is connected. Start an outbound conversation.' : 'Connect your telephony provider, then launch your first conversation.'}</p></div><Button onClick={integration ? onCreateCall : () => onNavigate('Numbers')} variant="contained" sx={{ bgcolor: '#76dfc0', color: '#10273a', '&:hover': { bgcolor: '#62d3b3' }, whiteSpace: 'nowrap' }}>{integration ? 'Start a call' : 'Connect Vobiz'}<ArrowOutwardRoundedIcon sx={{ ml: 1, fontSize: 16 }} /></Button></div></div>
    </Box>
  </>
}

function AgentsPage({ agents, loading, onCreate, onEdit, onArchive }: { agents: Agent[]; loading: boolean; onCreate: () => void; onEdit: (agent: Agent) => void; onArchive: (agent: Agent) => void }) { return <><PageIntro eyebrow="VOICE WORKSPACE" title="Voice agents" subtitle="Design the voices and instructions behind every conversation." action={<Button variant="contained" startIcon={<AddRoundedIcon />} onClick={onCreate}>New agent</Button>} /><Box className="page-grid" sx={{ mt: 3 }}>{loading ? <div className="span-12" style={{ textAlign: 'center', padding: 70 }}><CircularProgress size={25} /></div> : agents.length ? agents.map((a, i) => <div className="span-4" key={a.id}><Card className="agent-card"><Stack direction="row" justifyContent="space-between" alignItems="start"><div className="agent-avatar" style={{ background: ['#e7eaff', '#e4f7f1', '#fff1e6'][i % 3], color: ['#485edb', '#139d7f', '#cf8231'][i % 3] }}><SmartToyRoundedIcon /></div><StatusChip status={a.enabled ? 'ready' : 'archived'} /></Stack><Typography variant="h6" sx={{ mt: 2, fontSize: 16 }}>{a.name}</Typography><Typography sx={{ color: 'text.secondary', fontSize: 12, mt: .5 }}>{a.language} · {a.voice} · {a.speaking_style}</Typography><Divider sx={{ my: 2 }} /><Typography sx={{ color: 'text.secondary', fontSize: 12, lineHeight: 1.6, minHeight: 39 }}>{a.instructions || 'No custom instructions added.'}</Typography><Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mt: 1.5 }}><Typography sx={{ color: '#9aa3b4', fontSize: 10 }}>CREATED {new Date(a.created_at).toLocaleDateString()}</Typography><Stack direction="row"><Button size="small" onClick={() => onEdit(a)}>Edit</Button><Button size="small" color="error" onClick={() => onArchive(a)}>Archive</Button></Stack></Stack></Card></div>) : <div className="span-12"><Card><div className="empty-state"><div className="agent-avatar" style={{ margin: '0 auto 14px' }}><SmartToyRoundedIcon /></div><b style={{ color: '#36425a', fontSize: 14 }}>Create your first voice agent</b><div style={{ fontSize: 12, marginTop: 6 }}>Set a voice, language, and clear instructions for your callers.</div><Button sx={{ mt: 1.5 }} variant="contained" startIcon={<AddRoundedIcon />} onClick={onCreate}>Create agent</Button></div></Card></div>}</Box></> }

function CustomersPage({ connected, onConnect, customers, loading, error, selected, onSelect, keys, keysLoading, keysError, onCreate, onIssueKey, onRevokeKey }: { connected: boolean; onConnect: () => void; customers: Customer[]; loading: boolean; error: unknown; selected: Customer | null; onSelect: (customer: Customer) => void; keys: CustomerApiKey[]; keysLoading: boolean; keysError: unknown; onCreate: () => void; onIssueKey: () => void; onRevokeKey: (id: string) => void }) {
  const forbidden = axios.isAxiosError(error) && error.response?.status === 403
  return <><PageIntro eyebrow="PLATFORM ADMINISTRATION" title="Customers" subtitle="Each customer account isolates its own agents, numbers, calls, recordings, and API credentials." action={<Button variant="contained" startIcon={<AddRoundedIcon />} onClick={onCreate} disabled={!connected}>Provision customer</Button>} />
    <Box className="page-grid" sx={{ mt: 3 }}>
      <div className="span-12"><Card className="surface-card">
        <Alert severity="info" sx={{ mb: 2, fontSize: 12 }}>Connect with an allowlisted platform administrator OIDC token. Customer API keys act as credentials for one isolated customer account; a customer may have multiple keys for rotation.</Alert>
        {!connected ? <div className="empty-state"><div className="agent-avatar" style={{ margin: '0 auto 14px' }}><KeyRoundedIcon /></div><b style={{ color: '#36425a', fontSize: 14 }}>Connect as a platform administrator</b><div style={{ fontSize: 12, marginTop: 6 }}>Use an allowlisted OIDC identity with customer administration scopes.</div><Button sx={{ mt: 1.5 }} variant="contained" onClick={onConnect}>Connect API</Button></div> : loading ? <div style={{ textAlign: 'center', padding: 35 }}><CircularProgress size={24} /></div> : error ? <div className="error-box">{forbidden ? 'This session is not authorized for platform customer administration. It needs an allowlisted OIDC subject with platform:customers:read and platform:customers:write.' : errorMessage(error)}</div> : customers.length ? <Table size="small"><TableHead><TableRow>{['Customer', 'Customer ID', 'Billing', 'Created', ''].map(x => <TableCell className="table-head" key={x}>{x}</TableCell>)}</TableRow></TableHead><TableBody>{customers.map(customer => <TableRow key={customer.customer_id} hover selected={selected?.customer_id === customer.customer_id} onClick={() => onSelect(customer)} sx={{ cursor: 'pointer' }}><TableCell className="table-cell" sx={{ fontWeight: 700 }}>{customer.display_name}</TableCell><TableCell className="table-cell"><code>{customer.customer_id}</code></TableCell><TableCell className="table-cell"><Chip size="small" label={customer.billing_mode} color={customer.billing_mode === 'prepaid' ? 'primary' : 'default'} variant="outlined" sx={{ textTransform: 'capitalize' }} /></TableCell><TableCell className="table-cell">{new Date(customer.created_at).toLocaleDateString()}</TableCell><TableCell className="table-cell"><Button size="small" onClick={e => { e.stopPropagation(); onSelect(customer) }}>Manage keys</Button></TableCell></TableRow>)}</TableBody></Table> : <div className="empty-state"><div className="agent-avatar" style={{ margin: '0 auto 14px' }}><HubRoundedIcon /></div><b style={{ color: '#36425a', fontSize: 14 }}>No customers provisioned</b><div style={{ fontSize: 12, marginTop: 6 }}>Create a customer account and issue its first API key.</div><Button sx={{ mt: 1.5 }} variant="contained" startIcon={<AddRoundedIcon />} onClick={onCreate}>Provision customer</Button></div>}
      </Card></div>
      {selected && <div className="span-12"><Card className="surface-card"><Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" alignItems={{ sm: 'center' }} gap={1}><div><Typography variant="h6" sx={{ fontSize: 15 }}>{selected.display_name} · API keys</Typography><Typography sx={{ color: 'text.secondary', fontSize: 12, mt: .5 }}>All keys below are bound to this customer’s isolated data boundary.</Typography></div><Button variant="outlined" startIcon={<AddRoundedIcon />} onClick={onIssueKey}>Issue key</Button></Stack><Divider sx={{ my: 2 }} />
        {keysLoading ? <CircularProgress size={20} /> : keysError ? <div className="error-box">{errorMessage(keysError)}</div> : keys.length ? <Table size="small"><TableHead><TableRow>{['Name', 'Prefix', 'Permissions', 'Created', 'Last used', 'Expires', 'State', ''].map(x => <TableCell className="table-head" key={x}>{x}</TableCell>)}</TableRow></TableHead><TableBody>{keys.map(key => <TableRow key={key.id}><TableCell className="table-cell" sx={{ fontWeight: 700 }}>{key.name}</TableCell><TableCell className="table-cell"><code>{key.key_prefix}</code></TableCell><TableCell className="table-cell">{key.scopes.join(', ')}</TableCell><TableCell className="table-cell">{new Date(key.created_at).toLocaleDateString()}</TableCell><TableCell className="table-cell">{key.last_used_at ? new Date(key.last_used_at).toLocaleDateString() : 'Never'}</TableCell><TableCell className="table-cell">{key.expires_at ? new Date(key.expires_at).toLocaleDateString() : 'Never'}</TableCell><TableCell className="table-cell"><StatusChip status={key.revoked_at ? 'revoked' : 'active'} /></TableCell><TableCell className="table-cell">{!key.revoked_at && <Button color="error" size="small" onClick={() => onRevokeKey(key.id)}>Revoke</Button>}</TableCell></TableRow>)}</TableBody></Table> : <div className="empty-state">No keys yet. Issue a key for this customer’s integration.</div>}
      </Card></div>}
      <div className="span-12"><Card className="surface-card"><Typography variant="h6" sx={{ fontSize: 15 }}>Customer boundary</Typography><Typography sx={{ color: 'text.secondary', fontSize: 12, mt: .8, lineHeight: 1.6 }}>Provisioning creates the customer account and first credential together. The customer then uses its API key to configure multiple voice agents and phone numbers. Create replacement keys before revoking old keys to support safe rotation.</Typography></Card></div>
    </Box>
  </>
}

function ApiKeysPage({ keys, loading, error, onCreate, onRevoke }: { keys: ApiKey[]; loading: boolean; error: unknown; onCreate: () => void; onRevoke: (id: string) => void }) {
  const forbidden = axios.isAxiosError(error) && error.response?.status === 403
  return <><PageIntro eyebrow="DEVELOPER ACCESS" title="API keys" subtitle="Create and revoke tenant-scoped credentials for your applications." action={<Button variant="contained" startIcon={<AddRoundedIcon />} onClick={onCreate}>Create API key</Button>} />
    <Box className="page-grid" sx={{ mt: 3 }}><div className="span-12"><Card className="surface-card"><Alert severity="info" sx={{ mb: 2, fontSize: 12 }}>Full secrets are shown once at creation. The server stores only a hash. Use an OIDC session to manage keys; API keys cannot manage other keys.</Alert>{loading ? <div style={{ textAlign: 'center', padding: 35 }}><CircularProgress size={24} /></div> : error ? <div className="error-box">{forbidden ? 'This action requires an OIDC token with api_keys:read. Connect with an authorized OIDC session to view or create keys.' : errorMessage(error)}</div> : keys.length ? <Table size="small"><TableHead><TableRow>{['Name', 'Key prefix', 'Permissions', 'Created', 'Last used', 'Expires', 'State', ''].map(x => <TableCell className="table-head" key={x}>{x}</TableCell>)}</TableRow></TableHead><TableBody>{keys.map(key => <TableRow key={key.id} hover><TableCell className="table-cell" sx={{ fontWeight: 700 }}>{key.name}</TableCell><TableCell className="table-cell"><code>{key.key_prefix}</code></TableCell><TableCell className="table-cell">{key.scopes.join(', ')}</TableCell><TableCell className="table-cell">{new Date(key.created_at).toLocaleDateString()}</TableCell><TableCell className="table-cell">{key.last_used_at ? new Date(key.last_used_at).toLocaleDateString() : 'Never'}</TableCell><TableCell className="table-cell">{key.expires_at ? new Date(key.expires_at).toLocaleDateString() : 'Never'}</TableCell><TableCell className="table-cell"><StatusChip status={key.revoked_at ? 'revoked' : 'active'} /></TableCell><TableCell className="table-cell">{!key.revoked_at && <Button color="error" size="small" onClick={() => onRevoke(key.id)}>Revoke</Button>}</TableCell></TableRow>)}</TableBody></Table> : <div className="empty-state"><div className="agent-avatar" style={{ margin: '0 auto 14px' }}><KeyRoundedIcon /></div><b style={{ color: '#36425a', fontSize: 14 }}>No API keys yet</b><div style={{ fontSize: 12, marginTop: 6 }}>Create a limited-scope key for one of your services.</div><Button sx={{ mt: 1.5 }} variant="contained" startIcon={<AddRoundedIcon />} onClick={onCreate}>Create API key</Button></div>}</Card></div>
      <div className="span-12"><Card className="surface-card"><Typography variant="h6" sx={{ fontSize: 15 }}>Key safety</Typography><Stack direction={{ xs: 'column', md: 'row' }} gap={2} sx={{ mt: 1.5 }}><Info label="AUTHORIZATION" value="Bearer cv_live_…" /><Info label="STORAGE" value="SHA-256 digest only" /><Info label="MAXIMUM LIFETIME" value="365 days" /><Info label="SCOPE RULE" value="A subset of your OIDC permissions" /></Stack></Card></div>
    </Box></>
}

function CallsPage({ recent, statusId, setStatusId, statusLookup, setStatusLookup, statusQuery, postCallQuery, onCreate }: { recent: RecentCall[]; statusId: string; setStatusId: (v: string) => void; statusLookup: string; setStatusLookup: (v: string) => void; statusQuery: any; postCallQuery: any; onCreate: () => void }) {
  const lookup = () => setStatusLookup(statusId.trim())
  return <><PageIntro eyebrow="CALL OPERATIONS" title="Call logs" subtitle="Review recent calls and look up their status and post-call analysis." action={<Button variant="contained" startIcon={<AddRoundedIcon />} onClick={onCreate}>New call</Button>} />
    <Box className="page-grid" sx={{ mt: 3 }}><div className="span-12"><Card className="surface-card"><Stack direction={{ xs: 'column', sm: 'row' }} alignItems={{ sm: 'center' }} justifyContent="space-between" gap={2}><div><Typography variant="h6" sx={{ fontSize: 15 }}>Look up a call</Typography><Typography sx={{ color: 'text.secondary', fontSize: 12, mt: .5 }}>Paste a session ID to refresh its status and post-call analysis.</Typography></div><Stack direction="row" gap={1} sx={{ width: { xs: '100%', sm: 450 } }}><TextField fullWidth size="small" value={statusId} onChange={e => setStatusId(e.target.value)} onKeyDown={e => e.key === 'Enter' && lookup()} placeholder="Session ID" InputProps={{ startAdornment: <InputAdornment position="start"><SearchRoundedIcon fontSize="small" /></InputAdornment> }} /><Button variant="contained" onClick={lookup}>Look up</Button></Stack></Stack>{statusLookup && <Box sx={{ mt: 2.5, p: 2, bgcolor: '#f8f9fc', borderRadius: 2 }}>
      {statusQuery.isLoading ? <CircularProgress size={20} /> : statusQuery.isError ? <div className="error-box">{errorMessage(statusQuery.error)}</div> : statusQuery.data && <><Stack direction="row" justifyContent="space-between" alignItems="center"><div><Typography sx={{ fontWeight: 800, fontSize: 13 }}>Call session</Typography><Typography sx={{ fontSize: 11, color: 'text.secondary', mt: .3 }}>{statusQuery.data.session_id}</Typography></div><StatusChip status={statusQuery.data.status} /></Stack><Divider sx={{ my: 1.5 }} /><Stack direction="row" gap={3} flexWrap="wrap"><Info label="Provider" value={statusQuery.data.provider || '—'} /><Info label="Direction" value={statusQuery.data.direction || '—'} /><Info label="Started" value={statusQuery.data.started_at ? new Date(statusQuery.data.started_at).toLocaleString() : '—'} /><Info label="End reason" value={statusQuery.data.end_reason || '—'} /></Stack>{statusQuery.data.status === 'completed' && <Box sx={{ mt: 2 }}>{postCallQuery.isLoading ? <Typography sx={{ fontSize: 12 }}>Loading post-call analysis…</Typography> : postCallQuery.isError ? <Typography sx={{ color: 'text.secondary', fontSize: 12 }}>Post-call analysis is not available yet.</Typography> : postCallQuery.data && <><Typography sx={{ fontWeight: 800, fontSize: 13, mb: 1 }}>Post-call analysis</Typography><pre style={{ whiteSpace: 'pre-wrap', font: '12px DM Sans', padding: 14, background: 'white', borderRadius: 10, margin: 0 }}>{JSON.stringify(postCallQuery.data, null, 2)}</pre></>}</Box>}</>}
    </Box>}</Card></div><div className="span-12"><Card className="surface-card"><div className="section-heading" style={{ margin: '0 0 10px' }}><div><h2>Recent calls</h2><div className="page-subtitle" style={{ marginTop: 4 }}>This browser remembers the last 12 sessions you started.</div></div></div>{recent.length ? <Table size="small"><TableHead><TableRow>{['Destination', 'Provider', 'Date', 'Status', 'Session'].map(x => <TableCell className="table-head" key={x}>{x}</TableCell>)}</TableRow></TableHead><TableBody>{recent.map(c => <TableRow key={c.session_id} hover><TableCell className="table-cell" sx={{ fontWeight: 700 }}>{c.destination}</TableCell><TableCell className="table-cell">{c.provider}</TableCell><TableCell className="table-cell">{new Date(c.created_at).toLocaleString()}</TableCell><TableCell className="table-cell"><StatusChip status={c.status} /></TableCell><TableCell className="table-cell"><Button size="small" onClick={() => { setStatusId(c.session_id); setStatusLookup(c.session_id) }}>Details</Button></TableCell></TableRow>)}</TableBody></Table> : <div className="empty-state">No calls started from this browser yet.</div>}</Card></div></Box>
  </>
}
function Info({ label, value }: { label: string; value: string }) { return <div><div className="eyebrow">{label}</div><div style={{ fontSize: 12, fontWeight: 700, marginTop: 4 }}>{value}</div></div> }

function IntegrationsPage({ data, loading, form, onSave, busy }: { data?: Integration; loading: boolean; form: any; onSave: () => void; busy: boolean }) { return <><PageIntro eyebrow="CHANNELS & PROVIDERS" title="Phone numbers" subtitle="Connect Vobiz and manage the numbers used for inbound and outbound calls." /><Box className="page-grid" sx={{ mt: 3 }}><div className="span-8"><Card className="surface-card"><Stack direction="row" alignItems="center" justifyContent="space-between"><Stack direction="row" gap={1.5} alignItems="center"><div className="provider-mark">V</div><div><Typography variant="h6" sx={{ fontSize: 16 }}>Vobiz</Typography><Typography sx={{ color: 'text.secondary', fontSize: 11 }}>Phone calls · Voice API + media stream</Typography></div></Stack>{loading ? <CircularProgress size={18} /> : <StatusChip status={data ? 'configured' : 'not connected'} />}</Stack><Divider sx={{ my: 2.5 }} /><Stack component="form" gap={2} onSubmit={e => { e.preventDefault(); onSave() }}><Alert severity="info" sx={{ fontSize: 12 }}>Credentials are encrypted by the API and are never returned after saving. Re-enter both to rotate them.</Alert><Stack direction={{ xs: 'column', sm: 'row' }} gap={2}><TextField label="Auth ID" fullWidth {...form.register('auth_id', { required: 'Vobiz auth ID is required' })} error={!!form.formState.errors.auth_id} helperText={form.formState.errors.auth_id?.message} /><TextField label="Auth token" type="password" fullWidth {...form.register('auth_token', { required: 'Vobiz auth token is required' })} error={!!form.formState.errors.auth_token} helperText={form.formState.errors.auth_token?.message} /></Stack><TextField label="Vobiz phone number" placeholder="+15551234567" {...form.register('number', { required: true })} helperText="Add an active number in international format." /><TextField label="Default caller ID" placeholder="+15551234567" {...form.register('default_caller_id', { required: 'Caller ID is required' })} helperText="Must match the outbound-enabled phone number above." /><Stack direction="row" justifyContent="space-between" alignItems="center"><Typography sx={{ color: 'text.secondary', fontSize: 11 }}>{data ? `Saved credentials: ${data.credentials_configured.join(', ')}` : 'No credentials saved yet.'}</Typography><Button type="submit" variant="contained" disabled={busy}>{busy ? 'Saving…' : data ? 'Update integration' : 'Save integration'}</Button></Stack></Stack></Card></div><div className="span-4"><Card className="surface-card"><Typography variant="h6" sx={{ fontSize: 15 }}>Connection checklist</Typography><Stack gap={1.8} sx={{ mt: 2}}>{[['Vobiz account', !!data], ['Caller ID verified', Boolean(data?.phone_numbers?.some(n => n.outbound_enabled))], ['Public HTTPS callback', false], ['Webhook signature secret', false]].map(([label, ready]) => <Stack key={String(label)} direction="row" gap={1.2} alignItems="center"><CheckCircleRoundedIcon sx={{ fontSize: 17, color: ready ? '#14a481' : '#c8ced9' }} /><Typography sx={{ fontSize: 12, color: ready ? 'text.primary' : 'text.secondary', flex: 1 }}>{label}</Typography><StatusChip status={ready ? 'ready' : 'pending'} /></Stack>)}</Stack><Divider sx={{ my: 2 }} /><Typography sx={{ fontSize: 11, color: 'text.secondary', lineHeight: 1.6 }}>The backend also needs <code>VOBIZ_PUBLIC_URL</code>, route token, and webhook secret configured in its environment before inbound traffic can be enabled.</Typography></Card></div><div className="span-12"><div className="eyebrow" style={{ margin: '5px 0 10px' }}>COMING NEXT</div><Box className="page-grid">{['Twilio', 'Piopiy', 'TeleCMI'].map((name, i) => <div className="span-4" key={name}><Card className="integration-card"><div className="provider-mark" style={{ background: ['#e9f6ee', '#fff2e9', '#f1eaff'][i], color: ['#20985c', '#d77832', '#7653bd'][i] }}>{name[0]}</div><div style={{ flex: 1 }}><Typography sx={{ fontWeight: 800, fontSize: 13 }}>{name}</Typography><Typography sx={{ color: 'text.secondary', fontSize: 11 }}>Adapter not available yet</Typography></div><Chip size="small" label="Planned" variant="outlined" sx={{ fontSize: 10 }} /></Card></div>)}</Box></div></Box></> }

function WorkspacePage({ account, accountError, accountForm, onCreateAccount, plan, planForm, onSavePlan, busy }: { account?: Account; accountError: unknown; accountForm: any; onCreateAccount: () => void; plan?: Plan; planForm: any; onSavePlan: () => void; busy: boolean }) { const is404 = axios.isAxiosError(accountError) && accountError.response?.status === 404; return <><PageIntro eyebrow="WORKSPACE SETTINGS" title="Workspace & billing" subtitle="Manage your tenant profile, call limits, and voice usage rules." />
    <Box className="page-grid" sx={{ mt: 3 }}><div className="span-6"><Card className="surface-card" sx={{ height: '100%' }}><Typography variant="h6" sx={{ fontSize: 15 }}>Workspace profile</Typography><Typography sx={{ fontSize: 12, color: 'text.secondary', mt: .5 }}>Your workspace is scoped to the tenant claim in your identity token.</Typography><Divider sx={{ my: 2 }} />{account ? <Stack gap={1.5}><Info label="WORKSPACE NAME" value={account.display_name} /><Info label="TENANT ID" value={account.tenant_id} /><Info label="BILLING MODE" value={account.billing_mode} />{account.vertex_project && <Stack direction="row" gap={1} alignItems="center"><Info label="VERTEX PROJECT" value={account.vertex_project.status} /><StatusChip status={account.vertex_project.status} /></Stack>}</Stack> : <>{!is404 && accountError ? <div className="error-box">{errorMessage(accountError)}</div> : <Stack component="form" gap={2} onSubmit={e => { e.preventDefault(); onCreateAccount() }}><TextField label="Workspace name" placeholder="Acme Support" {...accountForm.register('display_name', { required: true })} /><Controller name="billing_mode" control={accountForm.control} render={({ field }) => <FormControl fullWidth><InputLabel>Billing mode</InputLabel><Select {...field} label="Billing mode"><MenuItem value="prepaid">Prepaid · add a managed balance</MenuItem><MenuItem value="postpaid">Postpaid · configure a credit limit</MenuItem></Select></FormControl>} /><Alert severity="info" sx={{ fontSize: 11 }}>Choose carefully: the account's billing mode is selected at creation and is not changed per call.</Alert><Button variant="contained" type="submit" disabled={busy}>Create workspace</Button></Stack>}</>}</Card></div>
    <div className="span-6"><Card className="surface-card"><Typography variant="h6" sx={{ fontSize: 15 }}>Voice billing plan</Typography><Typography sx={{ fontSize: 12, color: 'text.secondary', mt: .5 }}>Set usage rates and safeguards for this tenant.</Typography><Divider sx={{ my: 2 }} />{account ? <Stack component="form" gap={1.7} onSubmit={e => { e.preventDefault(); onSavePlan() }}><Stack direction="row" alignItems="center" justifyContent="space-between"><Typography sx={{ fontSize: 12, fontWeight: 700 }}>Allow voice calls</Typography><Controller name="voice_enabled" control={planForm.control} render={({ field }) => <Switch checked={field.value} onChange={field.onChange} color="success" />} /></Stack><Stack direction={{ xs: 'column', sm: 'row' }} gap={1.5}><TextField label="Currency" fullWidth {...planForm.register('currency', { required: true })} /><TextField label="Rate / minute (minor units)" type="number" fullWidth {...planForm.register('rate_per_minute_minor', { valueAsNumber: true, min: 1 })} /></Stack><Stack direction={{ xs: 'column', sm: 'row' }} gap={1.5}><TextField label="Max call seconds" type="number" fullWidth {...planForm.register('max_call_seconds', { valueAsNumber: true, min: 1 })} /><TextField label="Concurrent sessions" type="number" fullWidth {...planForm.register('max_concurrent_sessions', { valueAsNumber: true, min: 1 })} /></Stack>{account.billing_mode === 'prepaid' ? <TextField label="Prepaid balance (minor units)" type="number" {...planForm.register('prepaid_balance_minor', { valueAsNumber: true, min: 0 })} helperText="100 minor units = 1.00 currency unit." /> : <TextField label="Postpaid credit limit (minor units)" type="number" {...planForm.register('postpaid_credit_limit_minor', { valueAsNumber: true, min: 0 })} helperText="100 minor units = 1.00 currency unit." />}<Stack direction="row" alignItems="center" justifyContent="space-between"><Typography sx={{ fontSize: 12, fontWeight: 700 }}>Allow call recordings</Typography><Controller name="recording_allowed" control={planForm.control} render={({ field }) => <Switch checked={field.value} onChange={field.onChange} color="success" />} /></Stack><Alert severity="warning" sx={{ fontSize: 11 }}>Plan changes require the trusted OIDC <code>billing:admin</code> scope. API keys cannot change billing plans.</Alert><Button variant="contained" type="submit" disabled={busy}>{plan ? 'Save voice plan' : 'Create voice plan'}</Button></Stack> : <Alert severity="info">Create your workspace to configure a voice plan.</Alert>}</Card></div>
    <div className="span-12"><Card className="surface-card"><Typography variant="h6" sx={{ fontSize: 15 }}>Operational status</Typography><Typography sx={{ fontSize: 12, color: 'text.secondary', mt: .5 }}>Backend readiness checks, updated every minute.</Typography><Divider sx={{ my: 2 }} /><ReadinessPanel /></Card></div></Box></> }
function ReadinessPanel() { const q = useQuery({ queryKey: ['health'], queryFn: api.health, refetchInterval: 60000, retry: false }); if (q.isLoading) return <CircularProgress size={20} />; if (q.isError) return <div className="error-box">{errorMessage(q.error)}</div>; return <Box className="page-grid">{Object.entries(q.data.checks || {}).map(([name, value]) => <div className="span-4" key={name}><Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ p: 1.2, border: '1px solid #eef0f5', borderRadius: 2 }}><Typography sx={{ fontSize: 12, textTransform: 'capitalize' }}>{name.replaceAll('_', ' ')}</Typography><StatusChip status={value ? 'ready' : 'not_ready'} /></Stack></div>)}</Box> }

export default App
